package main

import "net/http"

func serveLogin(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Write([]byte(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/static/style.css"><title>Webhook Mailer</title></head><body class="login"><main class="card"><h1>Webhook Mailer</h1><p>接口推送与邮件转发管理</p><form id="login"><input name="username" placeholder="管理员账号" autocomplete="username" required><input name="password" placeholder="密码" type="password" autocomplete="current-password" required><button>登录</button><small id="error"></small></form></main><script>document.querySelector('#login').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(f))});if(r.ok)location='/admin';else document.querySelector('#error').textContent=(await r.json()).error}</script></body></html>`))
}
func serveAdmin(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Write([]byte(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/static/style.css"><title>管理后台</title></head><body><header><b>Webhook Mailer</b><button id="logout">退出登录</button></header><main><section><h2>推送接口 <button onclick="newHook()">新增接口</button></h2><div id="hooks"></div></section><section><h2>推送邮箱 <button onclick="newRecipient()">添加邮箱</button></h2><div id="recipients"></div></section><section><h2>发件 SMTP 设置</h2><form id="smtp"><input name="host" placeholder="SMTP 服务器" required><input name="port" type="number" placeholder="端口" required><input name="username" placeholder="用户名" required><input name="from_email" type="email" placeholder="发件邮箱" required><button>保存 SMTP 设置</button></form><p class="hint">SMTP 授权码从服务器环境变量 <code>SMTP_PASSWORD</code> 读取。</p></section></main><dialog id="dialog"><form method="dialog" id="editor"><h3></h3><div id="fields"></div><menu><button value="cancel">取消</button><button value="save">保存</button></menu></form></dialog><script src="/static/app.js"></script></body></html>`))
}
func serveCSS(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "text/css; charset=utf-8")
	w.Write([]byte(`*{box-sizing:border-box}body{margin:0;background:#f5f7fb;color:#172033;font:15px system-ui,-apple-system,"Microsoft YaHei",sans-serif}header{height:58px;background:#182640;color:white;display:flex;align-items:center;justify-content:space-between;padding:0 calc((100% - 1100px)/2)}main{max-width:1100px;margin:26px auto;display:grid;gap:20px}section,.card{background:#fff;border:1px solid #e4e8f0;border-radius:12px;padding:22px;box-shadow:0 4px 18px #0c1c3410}h1,h2{margin:0 0 16px}h2{font-size:18px}button{border:0;border-radius:7px;background:#2767d8;color:white;padding:8px 12px;cursor:pointer}header button{background:#ffffff20}input{width:100%;padding:10px;border:1px solid #cbd3e0;border-radius:7px;margin:5px 0}.login{min-height:100vh;display:grid;place-items:center}.login .card{width:min(390px,92vw)}.login button{width:100%;margin-top:8px}small{color:#c33131;display:block;margin-top:8px}.row{border-top:1px solid #edf0f5;padding:13px 0;display:flex;justify-content:space-between;gap:12px}.row:first-child{border:0}.meta{color:#67738a;font-size:13px;word-break:break-all}.hint{color:#67738a}dialog{border:0;border-radius:12px;padding:22px;min-width:min(420px,92vw);box-shadow:0 16px 60px #0004}menu{padding:0;display:flex;justify-content:flex-end;gap:8px}code{background:#edf1f7;padding:2px 4px;border-radius:4px}`))
}
func serveJS(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
	w.Write([]byte(`const $=s=>document.querySelector(s),api=async(p,o={})=>{let r=await fetch('/api/v1/'+p,{headers:{'Content-Type':'application/json'},...o});if(r.status===401){location='/';return}let d=await r.json();if(!r.ok)throw Error(d.error);return d};let recipients=[];async function load(){try{let[h,r,s]=await Promise.all([api('webhooks'),api('recipients'),api('smtp')]);recipients=r;$('#hooks').innerHTML=h.map(x=>'<div class="row"><div><b>'+x.name+'</b><div class="meta">'+x.url+'</div><div class="meta">'+(x.enabled?'已启用':'已暂停')+'</div></div><button onclick="editHook('+x.id+')">编辑</button></div>').join('')||'暂无接口';$('#recipients').innerHTML=r.map(x=>'<div class="row"><div><b>'+x.email+'</b><div class="meta">'+(x.enabled?'已启用':'已停用')+'</div></div><button onclick="editRecipient('+x.id+')">编辑</button></div>').join('')||'暂无邮箱';Object.entries(s).forEach(([k,v])=>$('#smtp [name='+k+']').value=v)}catch(e){alert(e.message)}}function modal(title,html,save){$('#editor h3').textContent=title;$('#fields').innerHTML=html;$('#dialog').showModal();$('#editor').onsubmit=async e=>{e.preventDefault();try{await save(Object.fromEntries(new FormData(e.target)));$('#dialog').close();load()}catch(x){alert(x.message)}}}function newHook(){modal('新增推送接口','<input name="name" placeholder="接口名称" required><label><input type="checkbox" name="enabled" checked> 启用</label>',x=>api('webhooks',{method:'POST',body:JSON.stringify({name:x.name,enabled:!!x.enabled})}))}async function editHook(id){let x=(await api('webhooks')).find(v=>v.id==id);modal('编辑推送接口','<input name="name" value="'+x.name+'" required><label><input type="checkbox" name="enabled" '+(x.enabled?'checked':'')+'> 启用</label><p class="hint">推送地址：'+x.url+'</p>',v=>api('webhooks/'+id,{method:'PUT',body:JSON.stringify({name:v.name,enabled:!!v.enabled})}))}function newRecipient(){modal('添加推送邮箱','<input name="email" type="email" placeholder="name@example.com" required>',x=>api('recipients',{method:'POST',body:JSON.stringify(x)}))}async function editRecipient(id){let x=recipients.find(v=>v.id==id);modal('编辑推送邮箱','<input name="email" type="email" value="'+x.email+'" required><label><input type="checkbox" name="enabled" '+(x.enabled?'checked':'')+'> 启用</label>',v=>api('recipients/'+id,{method:'PUT',body:JSON.stringify({email:v.email,enabled:!!v.enabled})}))}$('#smtp').onsubmit=async e=>{e.preventDefault();try{let x=Object.fromEntries(new FormData(e.target));x.port=+x.port;await api('smtp',{method:'PUT',body:JSON.stringify(x)});alert('已保存')}catch(x){alert(x.message)}};$('#logout').onclick=async()=>{await fetch('/api/auth/logout',{method:'POST'});location='/'};load();`))
}
